// Recordings drive the real app, so they need the full local stack:
// backend on :9000, `npm run preview` on :4000, a restored DB, and fresh
// auth state from `npx playwright test --project=setup` in care_fe.
export default defineConfig({
  testDir: "./recordings",
  testMatch: /.*\.demo\.ts/,
  timeout: 180_000,
  // Recordings share fixture data, so they must not race each other.
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: "list",
  outputDir: "./test-results",
  use: {
    ...devices["Desktop Chrome"],
    baseURL: "http://localhost:4000",
    storageState: "../care_fe/tests/.auth/user.json",
    viewport: { width: 1280, height: 720 },
    video: {
      mode: "on",
      size: { width: 1280, height: 720 },
      show: {
        actions: { duration: 800, position: "top-right", fontSize: 14 },
        test: { level: "step", position: "top-left", fontSize: 14 },
      },
    },
    // Human-watchable pacing. Without this the flow is a blur.
    launchOptions: { slowMo: 400 },
    navigationTimeout: 30_000,
    actionTimeout: 15_000,
  },
  projects: [{ name: "docs" }],
});
