{"content": "import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

import type { Page } from "@playwright/test";

const CARE_FE = path.resolve(process.cwd(), "../care_fe");

function readMeta(file: string): string {
  const metaPath = path.join(CARE_FE, "tests/.auth", file);
  if (!fs.existsSync(metaPath)) {
    throw new Error(
      `Missing ${metaPath}. Run \`npx playwright test --project=setup\` in care_fe first.`,
    );
  }
  const { id } = JSON.parse(fs.readFileSync(metaPath, "utf8"));
  if (!id) throw new Error(`No id in ${metaPath}`);
  return id;
}

export const getFacilityId = () => readMeta("facilityMeta.json");
export const getPatientId = () => readMeta("patientMeta.json");

/**
 * Closes the page to finalize the video, converts it to H.264 MP4, and writes a
 * poster frame next to it. Returns the MP4 path.
 */
export async function saveRecording(
  page: Page,
  outputPath: string,
): Promise<string> {
  const video = page.video();
  if (!video) throw new Error("Video recording is not enabled.");

  await page.close();

  const webm = path.resolve("test-results", `${path.basename(outputPath)}.webm`);
  fs.mkdirSync(path.dirname(webm), { recursive: true });
  await video.saveAs(webm);

  const mp4 = path.resolve(outputPath);
  fs.mkdirSync(path.dirname(mp4), { recursive: true });

  // yuv420p is mandatory, or Safari and QuickTime refuse to play the file.
  execFileSync("ffmpeg", [
    "-y",
    "-i", webm,
    "-c:v", "libx264",
    "-profile:v", "high",
    "-pix_fmt", "yuv420p",
    "-crf", "26",
    "-preset", "slow",
    "-movflags", "+faststart",
    "-an",
    mp4,
  ]);

  execFileSync("ffmpeg", [
    "-y",
    "-i", mp4,
    "-vframes", "1",
    mp4.replace(/\.mp4$/, ".png"),
  ]);

  return mp4;
}
