{"content": "import { expect, test } from "@playwright/test";

import {
  getFacilityId,
  getPatientId,
  saveRecording,
} from "../../support/care";

// Records entry point A (patient home page) of "How to Create an Encounter".
// Each test.step title matches a step heading in the flow doc, because
// Playwright burns the step title into the video as a caption.
test("How to Create an Encounter", async ({ page }) => {
  const facilityId = getFacilityId();
  const patientId = getPatientId();

  await test.step("1. Open the Initiate Patient Encounter form", async () => {
    await page.goto(`/facility/${facilityId}/patient/${patientId}`);
    const createEncounter = page.getByRole("button", {
      name: "Create Encounter",
    });
    await expect(createEncounter).toBeVisible();
    await createEncounter.click();
  });

  await test.step("2. Complete the encounter details", async () => {
    await page.getByRole("button", { name: "Ambulatory" }).click();
  });

  await test.step("3. Submit the form", async () => {
    await page
      .getByRole("button", { name: "Create Encounter" })
      .last()
      .click();
    await expect(page.getByText("Encounter created successfully")).toBeVisible();
  });

  // Hold on the final screen so the outcome is visible in the video.
  await page.waitForTimeout(2000);

  await saveRecording(page, "Clinical/Encounter/media/create_an_encounter.mp4");
});
