import path from "node:path";

// care_fe/.env.local ships pointing at a live shared API and also lists production URLs.
// Recording against those would create real patients and encounters, so fail closed.
export default function assertLocalBackend(): void {
  const careFe = path.resolve(process.cwd(), "../care_fe");
  const files = [".env.local", ".env"].map((f) => path.join(careFe, f));

  let apiUrl: string | undefined;
  for (const file of files) {
    if (!fs.existsSync(file)) continue;
    for (const line of fs.readFileSync(file, "utf8").split("\n")) {
      const match = line.match(/^\s*REACT_CARE_API_URL\s*=\s*(\S+)/);
      if (match) {
        apiUrl = match[1];
        break;
      }
    }
    if (apiUrl) break;
  }

  if (!apiUrl) {
    throw new Error(
      "REACT_CARE_API_URL is not set in care_fe/.env.local or care_fe/.env. " +
        "Refusing to record against an unknown backend.",
    );
  }

  const host = new URL(apiUrl).hostname;
  if (!["localhost", "127.0.0.1", "0.0.0.0", "::1"].includes(host)) {
    throw new Error(
      `REFUSING TO RECORD: care_fe targets a non-local backend (${apiUrl}).\n` +
        "Recordings create patients and encounters. Point REACT_CARE_API_URL at " +
        "localhost and restart the dev server before recording.",
    );
  }
}
