// Generates the Claude Code plugin in ./plugin from the canonical VS Code
// customisations in ./.github. Run after editing anything under .github/.
import { cpSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "plugin");

/** VS Code tool aliases → Claude Code tool names. */
const TOOLS = {
  read: ["Read"],
  search: ["Glob", "Grep"],
  edit: ["Read", "Write", "Edit"],
  execute: ["Bash"],
  agent: ["Task"],
  todo: ["TodoWrite"],
  web: ["WebFetch", "WebSearch"],
};

/** Model tier is inferred from the first entry of the VS Code model array. */
const modelFor = (value) => {
  const first = String(Array.isArray(value) ? value[0] : (value ?? "")).toLowerCase();
  if (first.includes("opus")) return "opus";
  if (first.includes("haiku")) return "haiku";
  return "sonnet";
};

/** Paths that differ once the files live inside an installed plugin. */
const rewrite = (body) =>
  body
    .replaceAll(
      /care_docs\/\.github\/skills\/care-docs-generation/g,
      "${CLAUDE_PLUGIN_ROOT}/skills/care-docs-generation",
    )
    .replaceAll(/\.\.\/\.\.\/\.\.\/\.\.\/recordings/g, "${CLAUDE_PLUGIN_ROOT}/recordings")
    .replaceAll("~/ohc.network/care_fe", "$CARE_FE_DIR")
    .replaceAll("~/ohc.network/care_docs", "$CARE_DOCS_DIR")
    .replaceAll("~/ohc.network/care", "$CARE_DIR");

function splitFrontmatter(text) {
  const match = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
  if (!match) throw new Error("Missing YAML frontmatter");
  return { yaml: match[1], body: match[2] };
}

// Deliberately tiny: the frontmatter we author is flat scalars, arrays and quoted
// strings, so a YAML dependency would be overkill.
function parseFrontmatter(yaml) {
  const out = {};
  const lines = yaml.split(/\r?\n/);
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const match = line.match(/^([A-Za-z-]+):\s*(.*)$/);
    if (!match) continue;
    const [, key] = match;
    let raw = match[2];
    while (raw.trimEnd().endsWith(",") || (raw.includes("[") && !raw.includes("]"))) {
      i += 1;
      raw += lines[i] ?? "";
    }
    raw = raw.trim();
    if (raw.startsWith("[")) {
      out[key] = raw
        .slice(1, raw.lastIndexOf("]"))
        .split(",")
        .map((v) => v.trim().replace(/^['"]|['"]$/g, ""))
        .filter(Boolean);
    } else {
      out[key] = raw.replace(/^['"]|['"]$/g, "");
    }
  }
  return out;
}

function buildAgents() {
  const src = join(ROOT, ".github/agents");
  const dest = join(OUT, "agents");
  mkdirSync(dest, { recursive: true });

  for (const file of readdirSync(src).filter((f) => f.endsWith(".agent.md"))) {
    const { yaml, body } = splitFrontmatter(readFileSync(join(src, file), "utf8"));
    const fm = parseFrontmatter(yaml);

    const tools = [
      ...new Set((fm.tools ?? []).flatMap((t) => TOOLS[t] ?? [])),
    ];

    // Claude Code identifies subagents by filename, so keep it stable and kebab-case.
    const name = file.replace(/\.agent\.md$/, "");
    const frontmatter = [
      "---",
      `name: ${name}`,
      `description: ${JSON.stringify(fm.description ?? "")}`,
      `model: ${modelFor(fm.model)}`,
      tools.length ? `tools: ${tools.join(", ")}` : null,
      "---",
      "",
    ]
      .filter(Boolean)
      .join("\n");

    writeFileSync(join(dest, `${name}.md`), frontmatter + rewrite(body));
  }
}

function buildSkill() {
  const src = join(ROOT, ".github/skills/care-docs-generation");
  const dest = join(OUT, "skills/care-docs-generation");
  rmSync(dest, { recursive: true, force: true });
  cpSync(src, dest, { recursive: true });

  // Rewrite paths inside every markdown file the skill ships.
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (entry.name.endsWith(".md")) {
        writeFileSync(path, rewrite(readFileSync(path, "utf8")));
      }
    }
  };
  walk(dest);
}

